SELECT
    ,
    ,
    w.warehouse_name AS warehouseName,
    w.status AS warehouseStatus,
    eu.nickname AS userName


    t.is_deleted = 0


        AND (t.check_no LIKE CONCAT('%', #{q.keyword}, '%')
        OR w.warehouse_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR t.remark LIKE CONCAT('%', #{q.keyword}, '%')
        OR eu.nickname LIKE CONCAT('%', #{q.keyword}, '%'))



        AND t.warehouse_id = #{q.warehouseId}


        AND t.check_type = #{q.checkType}


        AND t.status = #{q.status}



        AND t.user_id = #{q.userId}



        AND t.create_time >= #{q.createBeginTime}


        AND t.create_time <= #{q.createEndTime}



ORDER BY t.id DESC

SELECT i.id, i.sku_id, i.warehouse_id, i.stock, i.locked_stock, i.cost_price, (i.stock - i.locked_stock) AS availableStock, p.id AS productId, p.product_name AS productName, p.product_code AS productCode, sk.spec_text AS specText FROM shop_erp_inventory i INNER JOIN shop_product_sku sk ON sk.id = i.sku_id AND sk.is_deleted = 0 INNER JOIN shop_product p ON p.id = sk.product_id AND p.is_deleted = 0 WHERE i.is_deleted = 0 AND i.warehouse_id = #{warehouseId}
AND (p.product_name LIKE CONCAT('%', #{keyword}, '%') OR p.product_code LIKE CONCAT('%', #{keyword}, '%') OR sk.spec_text LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.id DESC, i.id DESC LIMIT #{limit}
